'use strict';
(()=>{
const {Engine,Bodies,Body,Composite,Events}=Matter,$=id=>document.getElementById(id),W=440,H=680,LINE=110,FLOOR=648,STEP=1000/120;
const tiers=[
['4486.jpg','#ff87ab',15,.5,.5],['3452.jpg','#bc9aff',21,.55,.52],['3085.jpg','#ffaf62',28,.5,.50],['3086.jpg','#7be0ef',35,.5,.48],['3090.jpg','#9be08a',44,.5,.48],['5545.jpg','#ffc95f',54,.40,.48],['579.jpg','#729eff',65,.5,.43],['596.jpg','#f477e3',77,.50,.48],['598.jpg','#e9d26b',90,.55,.65],['6481.webp','#58d5b3',106,.5,.48],['3324.png','#ffdf72',124,.5,.49]
];
const engine=Engine.create({enableSleeping:true,positionIterations:10,velocityIterations:8});engine.gravity.y=1.3;
const canvas=$('game'),ctx=canvas.getContext('2d'),assets=tiers.map(t=>{const im=new Image();im.src='portraits/'+t[0];im.onload=refreshPreviews;return im});
let score=0,best=0,highest=0,current=randomTier(),next=randomTier(),aim=W/2,readyAt=0,paused=false,over=false,activePointer=null,particles=[],rings=[],pending=[],combo=0,lastMerge=-10000,lastTime=0,accumulator=0,shake=0,comboTimer,audio,sound=true;
try{const stored=JSON.parse(localStorage.getItem('woojin-merge-record-v1'));best=Math.max(0,Number(stored?.best)||0);highest=Math.min(10,Math.max(0,Number(stored?.highest)||0))}catch{}
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function randomTier(){const n=Math.random();return n<.3?0:n<.57?1:n<.78?2:n<.93?3:4}
function balls(){return Composite.allBodies(engine.world).filter(b=>Number.isInteger(b.plugin.tier))}
function makeBall(t,x,y,age=0){const r=tiers[t][2],ball=Bodies.circle(clamp(x,18+r,W-18-r),Math.min(y,FLOOR-r),r,{restitution:.13,friction:.22,frictionStatic:.5,frictionAir:.003,density:.0015,slop:.03},48);ball.plugin={tier:t,born:engine.timing.timestamp-age,consumed:false,overflow:0};Composite.add(engine.world,ball);return ball}
function walls(){Composite.add(engine.world,[Bodies.rectangle(4,260,28,850,{isStatic:true,friction:.25}),Bodies.rectangle(436,260,28,850,{isStatic:true,friction:.25}),Bodies.rectangle(220,665,460,34,{isStatic:true,friction:.3})])}walls();
function record(){best=Math.max(best,score);try{localStorage.setItem('woojin-merge-record-v1',JSON.stringify({best,highest}))}catch{}$('score').textContent=score.toLocaleString('ko-KR');$('best').textContent=best.toLocaleString('ko-KR');$('discovered').textContent=(highest+1)+' / 11 발견';document.querySelectorAll('.evo').forEach((e,i)=>e.classList.toggle('seen',i<=highest))}
function save(){record();try{localStorage.setItem('woojin-merge-session-v1',JSON.stringify({version:1,score,current,next,over,balls:balls().map(b=>({t:b.plugin.tier,x:b.position.x,y:b.position.y,angle:b.angle,vx:b.velocity.x,vy:b.velocity.y}))}))}catch{}}
function face(c,t,x,y,r,angle=0,alpha=1){const [file,color,,cx,cy]=tiers[t],im=assets[t];c.save();c.globalAlpha=alpha;c.translate(x,y);c.rotate(angle);c.beginPath();c.arc(0,0,r,0,Math.PI*2);c.fillStyle=color;c.fill();c.save();c.clip();if(im?.naturalWidth){const size=Math.min(im.width,im.height)*.83,sx=clamp(im.width*cx-size/2,0,im.width-size),sy=clamp(im.height*cy-size/2,0,im.height-size);c.drawImage(im,sx,sy,size,size,-r,-r,r*2,r*2)}else{c.fillStyle='#20314b';c.fillRect(-r,-r,2*r,2*r);c.fillStyle=color;c.font=`bold ${r}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(t+1,0,0)}c.restore();c.lineWidth=Math.max(3,r*.065);c.strokeStyle=color;c.stroke();c.beginPath();c.arc(-r*.18,-r*.22,r*.63,Math.PI*1.1,Math.PI*1.65);c.strokeStyle='#ffffff55';c.lineWidth=1.5;c.stroke();c.restore();const badge=Math.max(8,Math.min(16,r*.25));c.save();c.globalAlpha=alpha;c.beginPath();c.arc(x+r*.64,y+r*.65,badge,0,Math.PI*2);c.fillStyle=color;c.fill();c.fillStyle='#112032';c.font=`bold ${badge*1.25}px sans-serif`;c.textAlign='center';c.textBaseline='middle';c.fillText(t+1,x+r*.64,y+r*.65);c.restore()}
function refreshPreviews(){if(!document.querySelector('.evo'))return;for(let i=0;i<11;i++){const c=$('evo'+i),x=c.getContext('2d');x.clearRect(0,0,80,80);face(x,i,36,35,29)}for(const [id,t,r] of [['next',next,27],['goal',10,60]]){const c=$(id),x=c.getContext('2d');x.clearRect(0,0,c.width,c.height);face(x,t,c.width/2-3,c.height/2-3,r)}}
$('evolution').innerHTML=tiers.map((_,i)=>`<div class="evo"><canvas id="evo${i}" width="80" height="80" aria-label="${i+1}단계 우진"></canvas><small>${i+1}단계</small></div>`).join('');
function tone(t,drop=false){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const now=audio.currentTime,o=audio.createOscillator(),g=audio.createGain();o.type=drop?'sine':'triangle';o.frequency.setValueAtTime(drop?220:260+t*65,now);o.frequency.exponentialRampToValueAtTime(drop?100:520+t*70,now+.13);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.18);o.connect(g);g.connect(audio.destination);o.start();o.stop(now+.19)}catch{}}
function burst(x,y,t){const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;rings.push({x,y,r:tiers[t][2],born:engine.timing.timestamp,color:tiers[t][1]});if(!reduced){shake=Math.min(5,2+t*.3);for(let i=0;i<18;i++){const a=Math.random()*Math.PI*2,v=1+Math.random()*3;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,color:tiers[t][1],life:45,max:45})}}}
function scan(event){for(const pair of event.pairs){const a=pair.bodyA,b=pair.bodyB;if(!Number.isInteger(a.plugin.tier)||a.plugin.tier!==b.plugin.tier||a.plugin.consumed||b.plugin.consumed)continue;a.plugin.consumed=b.plugin.consumed=true;pending.push([a,b])}}
let lastImpact=-1000;Events.on(engine,'collisionStart',e=>{if(engine.timing.timestamp-lastImpact<100)return;const hit=e.pairs.find(({bodyA:a,bodyB:b})=>(Number.isInteger(a.plugin.tier)||Number.isInteger(b.plugin.tier))&&Math.hypot(a.velocity.x-b.velocity.x,a.velocity.y-b.velocity.y)>2.5);if(hit){lastImpact=engine.timing.timestamp;tone(0,true)}});Events.on(engine,'collisionStart',scan);Events.on(engine,'collisionActive',scan);
function mergePending(){for(const [a,b]of pending){if(!Composite.get(engine.world,a.id,'body')||!Composite.get(engine.world,b.id,'body'))continue;const t=a.plugin.tier,x=(a.position.x+b.position.x)/2,y=(a.position.y+b.position.y)/2,vx=(a.velocity.x+b.velocity.x)/2,vy=(a.velocity.y+b.velocity.y)/2;Composite.remove(engine.world,a);Composite.remove(engine.world,b);if(t<10){const fresh=makeBall(t+1,x,y);Body.setVelocity(fresh,{x:clamp(vx,-2,2),y:clamp(vy,-2,2)});Body.setAngularVelocity(fresh,(a.angularVelocity+b.angularVelocity)/2);highest=Math.max(highest,t+1);score+=(t+1)*(t+2)/2;burst(x,y,t+1)}else{score+=66;burst(x,y,10)}const now=engine.timing.timestamp;combo=now-lastMerge<1700?combo+1:1;lastMerge=now;tone(t);if(combo>1||t>=9){$('combo').textContent=t===10?'전설의 더블 우진!':t===9?'전설의 우진 등장!':combo+' CHAIN!';$('combo').classList.add('show');clearTimeout(comboTimer);comboTimer=setTimeout(()=>$('combo').classList.remove('show'),1000)}record()}pending=[]}
function drop(){if(paused||over||engine.timing.timestamp<readyAt)return false;makeBall(current,aim,54);highest=Math.max(highest,current);record();tone(0,true);current=next;next=randomTier();aim=clamp(aim,18+tiers[current][2],W-18-tiers[current][2]);readyAt=engine.timing.timestamp+600;refreshPreviews();canvas.focus({preventScroll:true});return true}
function showOverlay(title,text,label){$('overlayTitle').textContent=title;$('overlayText').textContent=text;$('resume').textContent=label;$('overlay').classList.remove('hidden');$('resume').focus({preventScroll:true})}
function pause(){if(over)return;paused=!paused;activePointer=null;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'게임 계속하기':'일시정지');if(paused){showOverlay('잠깐 쉬어가기','구슬도 잠깐 쉬는 중이야.','계속하기');save()}else{$('overlay').classList.add('hidden');canvas.focus({preventScroll:true})}}
function gameOver(){if(over)return;over=true;activePointer=null;save();showOverlay('우진이가 꽉 찼어!','이번 점수 '+score.toLocaleString('ko-KR')+' · 최고 '+best.toLocaleString('ko-KR'),'다시 도전하기')}
function reset(){Composite.clear(engine.world,false);Engine.clear(engine);walls();score=0;current=randomTier();next=randomTier();over=paused=false;readyAt=0;pending=[];particles=[];rings=[];combo=0;lastMerge=-10000;activePointer=null;aim=W/2;clearTimeout(comboTimer);$('combo').classList.remove('show');$('overlay').classList.add('hidden');$('pause').textContent='Ⅱ';record();refreshPreviews();save();canvas.focus({preventScroll:true})}
function step(){Engine.update(engine,STEP);mergePending();let danger=false;for(const b of balls()){if(b.speed>14)Body.setVelocity(b,{x:clamp(b.velocity.x,-12,12),y:clamp(b.velocity.y,-14,14)});if(engine.timing.timestamp-b.plugin.born>1800&&b.position.y-tiers[b.plugin.tier][2]<LINE){b.plugin.overflow+=STEP;danger=true;if(b.plugin.overflow>=1500)gameOver()}else b.plugin.overflow=0}canvas.dataset.danger=String(danger)}
function draw(){ctx.clearRect(0,0,W,H);ctx.save();if(shake>.05){ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);shake*=.9}const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#142b40');bg.addColorStop(1,'#101c2d');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);ctx.fillStyle='#ffffff04';for(let y=130;y<640;y+=28)for(let x=32;x<420;x+=28)ctx.fillRect(x,y,2,2);ctx.strokeStyle=canvas.dataset.danger==='true'?'#ff6969':'#e18e8a88';ctx.lineWidth=1.5;ctx.setLineDash([7,7]);ctx.beginPath();ctx.moveTo(20,LINE);ctx.lineTo(420,LINE);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#cc9d9d';ctx.font='10px sans-serif';ctx.fillText('가득 차면 위험해!',24,LINE-9);ctx.fillStyle='#344e65';ctx.fillRect(0,110,18,H-110);ctx.fillRect(422,110,18,H-110);ctx.fillRect(0,FLOOR,W,H-FLOOR);for(const b of balls())face(ctx,b.plugin.tier,b.position.x,b.position.y,tiers[b.plugin.tier][2],b.angle);if(!over){const r=tiers[current][2],ready=engine.timing.timestamp>=readyAt;ctx.setLineDash([4,7]);ctx.strokeStyle='#9bdfd54d';ctx.beginPath();ctx.moveTo(aim,54+r);ctx.lineTo(aim,FLOOR);ctx.stroke();ctx.setLineDash([]);face(ctx,current,aim,54,r,0,ready?1:.4)}for(const r of rings){const age=(engine.timing.timestamp-r.born)/600;if(age>1)continue;ctx.globalAlpha=1-age;ctx.strokeStyle=r.color;ctx.lineWidth=4*(1-age);ctx.beginPath();ctx.arc(r.x,r.y,r.r+age*35,0,Math.PI*2);ctx.stroke()}rings=rings.filter(r=>engine.timing.timestamp-r.born<600);ctx.globalAlpha=1;for(const p of particles){ctx.globalAlpha=p.life/p.max;ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore();$('drop').disabled=paused||over||engine.timing.timestamp<readyAt}
let particleAccumulator=0;function frame(now){if(!lastTime)lastTime=now;const elapsed=Math.min(100,now-lastTime);lastTime=now;if(!paused&&!over&&!document.hidden){accumulator+=elapsed;let steps=0;while(accumulator>=STEP&&steps++<12){step();accumulator-=STEP;if(over)break}particleAccumulator+=elapsed;while(particleAccumulator>=16.666){for(const p of particles){p.x+=p.vx;p.y+=p.vy;p.vy+=.04;p.life--}particles=particles.filter(p=>p.life>0);particleAccumulator-=16.666}}else accumulator=0;draw();requestAnimationFrame(frame)}
function aimAt(clientX){const r=canvas.getBoundingClientRect();aim=clamp((clientX-r.left)*W/r.width,18+tiers[current][2],W-18-tiers[current][2])}
canvas.addEventListener('pointerdown',e=>{if(paused||over||activePointer!==null||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();activePointer=e.pointerId;aimAt(e.clientX);canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(activePointer===e.pointerId||(e.pointerType==='mouse'&&activePointer===null))aimAt(e.clientX)});canvas.addEventListener('pointerup',e=>{if(activePointer!==e.pointerId)return;e.preventDefault();aimAt(e.clientX);activePointer=null;drop()});canvas.addEventListener('pointercancel',()=>activePointer=null);canvas.addEventListener('lostpointercapture',()=>activePointer=null);canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','Enter','Escape'].includes(e.key))e.preventDefault();if(e.key==='Escape')pause();if(paused||over)return;if(e.key==='ArrowLeft')aim=clamp(aim-12,18+tiers[current][2],W-18-tiers[current][2]);if(e.key==='ArrowRight')aim=clamp(aim+12,18+tiers[current][2],W-18-tiers[current][2]);if((e.key===' '||e.key==='Enter')&&!e.repeat)drop()});
$('drop').onclick=drop;$('pause').onclick=pause;$('resume').onclick=()=>over?reset():pause();$('restart').onclick=()=>{if(!balls().length||over||confirm('이번 판을 처음부터 다시 시작할까? 최고 기록은 유지돼.'))reset()};$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♪':'♩';$('sound').setAttribute('aria-pressed',String(sound))};
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!paused&&!over)pause();lastTime=0});window.addEventListener('pagehide',save);setInterval(save,2000);
function restore(){try{const s=JSON.parse(localStorage.getItem('woojin-merge-session-v1'));if(s?.version!==1||s.over||!Array.isArray(s.balls)||!s.balls.length)return;score=Math.min(1e9,Math.max(0,Number(s.score)||0));if(Number.isInteger(s.current)&&s.current>=0&&s.current<=4)current=s.current;if(Number.isInteger(s.next)&&s.next>=0&&s.next<=4)next=s.next;for(const b of s.balls.slice(0,150)){if(!Number.isInteger(b.t)||b.t<0||b.t>10||!Number.isFinite(b.x)||!Number.isFinite(b.y))continue;const body=makeBall(b.t,b.x,clamp(b.y,-100,FLOOR),2000);Body.setAngle(body,Number.isFinite(b.angle)?b.angle:0);Body.setVelocity(body,{x:clamp(Number(b.vx)||0,-12,12),y:clamp(Number(b.vy)||0,-14,14)})}if(balls().length){paused=true;showOverlay('이어서 합쳐볼까?','지난번 구슬 배치를 불러왔어.','계속하기')}}catch{}}
restore();record();refreshPreviews();requestAnimationFrame(frame);
// Read-only debug entry point is installed only in local automated tests.
if(location.hostname==='127.0.0.1'||location.hostname==='localhost')window.mergeTest={engine,balls,makeBall,step,reset,drop,pause,tiers,get state(){return{score,best,paused,over,current,next,readyAt}},setCurrent(t){current=t},setAim(x){aim=x}};
})();
